        private static HashSet<int> _productIdsWithOrdersLastMonth;

        public static void RefreshDiscountCache()
        {
            var context = MiracleBootsEntities.GetContext();
            var today = DateTime.Today;
            var firstOfCurrent = new DateTime(today.Year, today.Month, 1);
            var firstOfPrev = firstOfCurrent.AddMonths(-1);
            var lastOfPrev = firstOfCurrent.AddDays(-1);

            _productIdsWithOrdersLastMonth = new HashSet<int>(
                context.OrderProducts
                    .Where(op => op.Orders.OrderDate >= firstOfPrev &&
                                 op.Orders.OrderDate <= lastOfPrev)
                    .Select(op => op.StockItems.ID_Product)
                    .Distinct()
                    .ToList());
        }
        public bool HasOrdersLastMonth
        {
            get
            {
                if (_productIdsWithOrdersLastMonth == null)
                    RefreshDiscountCache();
                return _productIdsWithOrdersLastMonth.Contains(ID_Product);
            }
        }
